            ['title' => 'Absolute Exclusion of Mania', 'icon' => '🚫', 'definition' => 'A lifetime absence of full manic episodes; a single manic episode immediately and permanently recodes the diagnosis to Bipolar I.'],
            ['title' => 'Depressive Morbidity Dominance', 'icon' => '🌧️', 'definition' => 'Patients spend over 75% of symptom time in severe, disabling depressive phases rather than hypomanic elevation.'],
