        'important_terms' => [
            ['term' => 'Hypomanic Switch', 'definition' => 'The induction of an abnormally elevated mood state triggered by pharmacological antidepressant treatment in a vulnerable individual.'],
            ['term' => 'Collateral History', 'definition' => 'Information obtained from family members, partners, or close friends to verify past periods of observable behavioral hypomania that the patient may minimize.'],
